// monomorphic: one shape, fast property access
function makePoint(x, y) {
  return { x, y };
}

// adding properties later changes the shape
const p = makePoint(1, 2);
p.z = 3; // now a different hidden class

localStorage.setItem('theme', 'dark');
const theme = localStorage.getItem('theme'); // 'dark'

// structured data needs serialisation
localStorage.setItem('user', JSON.stringify({ id: 1 }));

console.log('sync');
Promise.resolve().then(() => console.log('microtask'));
setTimeout(() => console.log('task'), 0);

// sync, microtask, task -- in both the browser and Node
